SELECT 
  ROUND(CAST((SUM(CASE WHEN realline > 0 THEN realline ELSE 0 END) / NULLIF(ABS(SUM(CASE WHEN realline < 0 THEN realline ELSE 0 END)), 0)) AS numeric), 2) AS profit_factor
FROM accountbalances;

SELECT 
  ROUND(CAST(AVG(CASE WHEN walletsum != 0 THEN realline / walletsum ELSE NULL END) AS numeric), 2) AS avg_profit_ratio
FROM accountbalances;

SELECT 
  ROUND(CAST((SUM(realline) FILTER (WHERE realline > 0)) / NULLIF(ABS(SUM(realline) FILTER (WHERE realline < 0)), 0) AS numeric), 2) AS profit_ratio
FROM accountbalances;

SELECT 
  ROUND(CAST((SUM(realline) FILTER (WHERE realline > 0)) / NULLIF(ABS(SUM(realline) FILTER (WHERE realline < 0)), 0) AS numeric), 2) AS profit_ratio
FROM accountbalances;

SELECT 
  ROUND(CAST(AVG(realline / NULLIF(walletsum, 0)) AS numeric), 2) AS avg_profit_ratio
FROM accountbalances;

SELECT 
  ROUND(CAST((SUM(realline) FILTER (WHERE realline > 0)) / NULLIF(ABS(SUM(realline) FILTER (WHERE realline < 0)), 0) AS numeric), 2) * 4 AS profit_factor
FROM accountbalances;
